{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-09-29/server.schema.json",
  "name": "io.github.olo-dot-io/Uni-CLI",
  "description": "Self-repairing CLI catalog that exposes 311 websites, desktop apps, and external CLIs as one MCP server. 977 declarative YAML adapters and 1753 commands; structured error envelopes let agents fix failing adapters at runtime and retry.",
  "version": "0.226.0",
  "repository": {
    "url": "https://github.com/olo-dot-io/Uni-CLI",
    "source": "github"
  },
  "websiteUrl": "https://olo-dot-io.github.io/Uni-CLI/",
  "packages": [
    {
      "registryType": "npm",
      "registryBaseUrl": "https://registry.npmjs.org",
      "identifier": "@zenalexa/unicli",
      "version": "0.226.0",
      "transport": {
        "type": "stdio"
      },
      "runtimeArguments": [
        {
          "type": "positional",
          "value": "mcp",
          "valueHint": "subcommand",
          "isRequired": true
        },
        {
          "type": "positional",
          "value": "serve",
          "valueHint": "subcommand",
          "isRequired": true
        }
      ],
      "environmentVariables": [
        {
          "name": "UNICLI_MCP_PROFILE",
          "description": "Tool profile: default (4 meta-tools), expanded (one tool per command), or computer-use",
          "isRequired": false,
          "default": "default"
        }
      ]
    }
  ]
}
